import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';

// Типи даних для авторизації
export interface AuthUser {
  id: string;
  username: string;
  firstName: string;
  lastName?: string;
  photoUrl?: string;
  role: string;
  permissions: string[];
  sessionId: string;
  loginTime: string;
}

export interface AuthState {
  isAuthenticated: boolean;
  user: AuthUser | null;
  sessionId: string | null;
  error: string | null;
  isLoading: boolean;
}

export interface AuthContextType {
  auth: AuthState;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => Promise<void>;
  validateSession: () => Promise<boolean>;
  clearError: () => void;
}

// Ініціалізація контексту з початковими значеннями
const initialAuthState: AuthState = {
  isAuthenticated: false,
  user: null,
  sessionId: null,
  error: null,
  isLoading: false,
};

const AuthContext = createContext<AuthContextType>({
  auth: initialAuthState,
  login: async () => false,
  logout: async () => {},
  validateSession: async () => false,
  clearError: () => {},
});

// Провайдер контексту авторизації
export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [auth, setAuth] = useState<AuthState>(initialAuthState);

  // Функція входу з логіном та паролем
  const login = useCallback(async (username: string, password: string): Promise<boolean> => {
    try {
      setAuth((prev) => ({ ...prev, isLoading: true, error: null }));
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password }),
      });
      if (response.ok) {
        const data = await response.json();
        if (data.success) {
          const user = {
            id: data.session.user.id,
            username: data.session.user.username,
            firstName: data.session.user.username || 'Admin',
            lastName: '',
            role: data.session.user.role,
            permissions: data.session.user.permissions || [],
            sessionId: data.session.sessionId,
            loginTime: new Date().toISOString(),
          };
          setAuth({
            isAuthenticated: true,
            user,
            sessionId: data.session.sessionId,
            error: null,
            isLoading: false,
          });
          localStorage.setItem('sessionId', data.session.sessionId);
          return true;
        } else {
          setAuth({
            ...initialAuthState,
            error: data.message || 'Помилка авторизації. Спробуйте ще раз.',
            isLoading: false,
          });
          return false;
        }
      } else {
        const errorData = await response.json().catch(() => ({}));
        setAuth({
          ...initialAuthState,
          error: errorData.detail || 'Помилка авторизації. Перевірте правильність логіна та пароля.',
          isLoading: false,
        });
        return false;
      }
    } catch (err: unknown) {
      console.error('Login error:', err);
      setAuth((prev) => ({
        ...prev,
        isLoading: false,
        error: err instanceof Error ? err.message : 'Помилка входу',
      }));
      return false;
    }
  }, []);

  // Функція виходу
  const logout = useCallback(async (): Promise<void> => {
    setAuth((prev) => ({ ...prev, isLoading: true }));
    try {
      const sessionId = auth.sessionId || localStorage.getItem('sessionId');
      if (!sessionId) {
        // Якщо немає сесії, просто очищаємо стан
        setAuth(initialAuthState);
        localStorage.removeItem('sessionId');
        return;
      }

      // Запит до API для завершення сесії
      const response = await fetch('/api/auth/logout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ sessionId }),
      });

      if (!response.ok) {
        console.warn('Помилка при виході з системи', response.status);
      }

      // Очищення стану в будь-якому випадку
      setAuth(initialAuthState);
      localStorage.removeItem('sessionId');
    } catch (error) {
      console.error('Помилка при виході:', error);
      // Очищаємо стан навіть при помилці
      setAuth(initialAuthState);
      localStorage.removeItem('sessionId');
    }
  }, [auth.sessionId]);

  // Валідація сесії
  const validateSession = useCallback(async (): Promise<boolean> => {
    const sessionId = auth.sessionId || localStorage.getItem('sessionId');
    if (!sessionId) {
      setAuth(initialAuthState);
      return false;
    }

    setAuth((prev) => ({ ...prev, isLoading: true }));
    try {
      const response = await fetch('/api/auth/validate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ sessionId }),
      });

      if (!response.ok) {
        setAuth(initialAuthState);
        localStorage.removeItem('sessionId');
        return false;
      }

      const data = await response.json();
      if (!data.valid) {
        setAuth(initialAuthState);
        localStorage.removeItem('sessionId');
        return false;
      }

      // Оновлення стану при валідній сесії
      setAuth({
        isAuthenticated: true,
        user: data.user,
        sessionId,
        error: null,
        isLoading: false,
      });
      return true;
    } catch (error) {
      console.error('Помилка валідації сесії:', error);
      setAuth(initialAuthState);
      localStorage.removeItem('sessionId');
      return false;
    }
  }, [auth.sessionId]);

  // Очищення помилки
  const clearError = useCallback(() => {
    setAuth((prev) => ({ ...prev, error: null }));
  }, []);

  // Перевірка сесії при завантаженні
  useEffect(() => {
    validateSession();
  }, [validateSession]);

  return (
    <AuthContext.Provider
      value={{
        auth,
        login,
        logout,
        validateSession,
        clearError,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

// Хук для використання контексту авторизації
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth має використовуватися в межах AuthProvider');
  }
  return context;
};
